window.GUILIB_SEARCH = [{"t":"GuiLib","u":"index.html","k":"page","s":"A UI library for Minecraft Fabric mods that works like web development: React-style components and hooks in a Kotlin DSL with HTML tag names"},{"t":"Why GuiLib","u":"index.html#why-guilib","k":"GuiLib","s":""},{"t":"Features","u":"index.html#features","k":"GuiLib","s":""},{"t":"Where to start","u":"index.html#where-to-start","k":"GuiLib","s":""},{"t":"Gallery","u":"index.html#gallery","k":"GuiLib","s":""},{"t":"Getting started","u":"getting-started.html","k":"page","s":"Add GuiLib to a Fabric mod, write a component and a stylesheet, and open it as a screen."},{"t":"Installation","u":"getting-started.html#installation","k":"Getting started","s":""},{"t":"Your first screen","u":"getting-started.html#your-first-screen","k":"Getting started","s":""},{"t":"Opening screens","u":"getting-started.html#opening-screens","k":"Getting started","s":""},{"t":"GuiLib.open","u":"getting-started.html#guilib-open","k":"function","s":"Opens a component as a Minecraft screen and returns it. Must be called on the client thread (use GuiLib.runOnUi otherwise).","c":""},{"t":"GuiLib.screen","u":"getting-started.html#guilib-screen","k":"function","s":"Creates the screen without opening it, e.g. to return it from a config button or ModMenu integration.","c":""},{"t":"GuiLib.close","u":"getting-started.html#guilib-close","k":"function","s":"Closes the current screen (e.g. from a close button: button(onClick = { GuiLib.close() }) ).","c":""},{"t":"GuiLib.currentScreen","u":"getting-started.html#guilib-currentscreen","k":"function","s":"The screen that is currently open, on every supported Minecraft version.","c":""},{"t":"GuiLib.runOnUi","u":"getting-started.html#guilib-runonui","k":"function","s":"Runs a block on the client (render) thread. State setters are already thread-safe; use this for other work such as opening screens from a ne","c":""},{"t":"Stylesheets & resources","u":"getting-started.html#stylesheets-resources","k":"Getting started","s":""},{"t":"Development workflow","u":"getting-started.html#development-workflow","k":"Getting started","s":""},{"t":"Components & hooks","u":"components.html","k":"page","s":"UIs are built from function components. Hooks give them state, effects and access to the document, exactly like React."},{"t":"Components","u":"components.html#components","k":"Components & hooks","s":""},{"t":"component","u":"components.html#component","k":"function","s":"Declares a function component. The render lambda runs with a ComponentScope receiver (hooks + DSL) and receives the props. Use a data class ","c":""},{"t":"Keys & lists","u":"components.html#keys-lists","k":"Components & hooks","s":""},{"t":"Text","u":"components.html#text","k":"Components & hooks","s":""},{"t":"State","u":"components.html#state","k":"Components & hooks","s":""},{"t":"useState","u":"components.html#usestate","k":"hook","s":"Local state. Use it as a delegate or destructure it like React. Assigning a different value re-renders the component. Setters may be called ","c":""},{"t":"useStateLazy","u":"components.html#usestatelazy","k":"hook","s":"State whose initial value is computed only on the first render.","c":""},{"t":"useRef","u":"components.html#useref","k":"hook","s":"A mutable box kept across renders. Changing current does not re-render. Good for timers, previous values and drag state.","c":""},{"t":"useElementRef","u":"components.html#useelementref","k":"hook","s":"A ref for an element. Pass it as ref = to any tag; ref.current is then the Element (bounding rect, focus, scroll position, …).","c":""},{"t":"useMemo","u":"components.html#usememo","k":"hook","s":"Caches a computed value until one of the dependencies changes ( == ).","c":""},{"t":"Effects","u":"components.html#effects","k":"Components & hooks","s":""},{"t":"useEffect","u":"components.html#useeffect","k":"hook","s":"Runs a side effect after the DOM was updated.","c":""},{"t":"useInterval","u":"components.html#useinterval","k":"hook","s":"Calls the callback every ms milliseconds while mounted. Always calls the latest lambda, so it sees current state.","c":""},{"t":"useDocumentEvent","u":"components.html#usedocumentevent","k":"hook","s":"Listens to an event on the whole document while mounted (like document.addEventListener in an effect). Runs before element handlers; call st","c":""},{"t":"Context","u":"components.html#context","k":"Components & hooks","s":""},{"t":"createContext","u":"components.html#createcontext","k":"function","s":"Creates a context with a default value, for passing data deep into the tree without props (themes, the current user, …).","c":""},{"t":"useContext","u":"components.html#usecontext","k":"hook","s":"Reads the value of the nearest Provider above, or the context's default. The component re-renders when the provided value changes.","c":""},{"t":"Document & misc","u":"components.html#document-misc","k":"Components & hooks","s":""},{"t":"useDocument","u":"components.html#usedocument","k":"hook","s":"The Document of the screen: viewportWidth / viewportHeight , focusedElement , focus(el) , addEventListener , setTimeout / setInterval , post","c":""},{"t":"useToast","u":"components.html#usetoast","k":"hook","s":"The toaster of this screen, for short notifications. See Toasts .","c":""},{"t":"useForceUpdate","u":"components.html#useforceupdate","k":"hook","s":"Returns a function that re-renders the component. An escape hatch; prefer state.","c":""},{"t":"classNames","u":"components.html#classnames","k":"function","s":"Joins class names and skips falsy ones, like the clsx package.","c":""},{"t":"Rules of hooks","u":"components.html#rules-of-hooks","k":"Components & hooks","s":""},{"t":"Differences from the web","u":"differences.html","k":"page","s":"GuiLib follows the web wherever it can. These are the places where it doesn't. Read this once; it saves time."},{"t":"Units & defaults","u":"differences.html#units-defaults","k":"Differences from the web","s":""},{"t":"API","u":"differences.html#api","k":"Differences from the web","s":""},{"t":"Rendering","u":"differences.html#rendering","k":"Differences from the web","s":""},{"t":"Text","u":"differences.html#text","k":"Differences from the web","s":""},{"t":"Not supported (yet)","u":"differences.html#not-supported-yet","k":"Differences from the web","s":""},{"t":"Recipes","u":"recipes.html","k":"page","s":"Short answers to common UI tasks."},{"t":"Layout","u":"recipes.html#layout","k":"Recipes","s":""},{"t":"Behaviour","u":"recipes.html#behaviour","k":"Recipes","s":""},{"t":"Animation","u":"recipes.html#animation","k":"Recipes","s":""},{"t":"A complete example","u":"recipes.html#a-complete-example","k":"Recipes","s":""},{"t":"Elements","u":"elements.html","k":"page","s":"Tag functions build elements with HTML names. Every tag takes the same common props and event handlers; children go in the trailing lambda."},{"t":"Common props","u":"elements.html#common-props","k":"Elements","s":""},{"t":"Structure & text","u":"elements.html#structure-text","k":"Elements","s":""},{"t":"GuiLib tags","u":"elements.html#guilib-tags","k":"Elements","s":""},{"t":"scroll","u":"elements.html#scroll","k":"GuiLib tag","s":"A block element with overflow: auto and a thin scrollbar. Any element with overflow: auto/scroll scrolls as well; scroll is a convenient def","c":""},{"t":"img","u":"elements.html#img","k":"tag","s":"An image from your resources (PNG or SVG). Its natural size is the image size; object-fit is supported.","c":""},{"t":"item","u":"elements.html#item","k":"GuiLib tag","s":"Renders a Minecraft item stack like in an inventory slot (16×16 by default; size it with CSS). Needs a loaded world.","c":""},{"t":"entity","u":"elements.html#entity","k":"GuiLib tag","s":"Renders a living entity scaled to fit its box, like the inventory player model (48×72 by default).","c":""},{"t":"FakePlayer","u":"elements.html#fakeplayer","k":"class","s":"Client-side player entities for entity(...) (package net.sbo.guilib.fabric.entity ). Every factory returns null when no world is loaded, so ","c":""},{"t":"Structure helpers","u":"elements.html#structure-helpers","k":"Elements","s":""},{"t":"fragment","u":"elements.html#fragment","k":"function","s":"Groups children without a wrapper element (like <>…</> ), e.g. to give a group of elements a key.","c":""},{"t":"portal","u":"elements.html#portal","k":"function","s":"Renders children into the overlay layer above everything else (like createPortal(children, document.body) ). Position the content with posit","c":""},{"t":"Fonts","u":"elements.html#fonts","k":"Elements","s":""},{"t":"Form controls","u":"controls.html","k":"page","s":"Ready-made, styleable controls. All of them are controlled like React: pass the current value, update your state in onChange ."},{"t":"Text","u":"controls.html#text","k":"Form controls","s":""},{"t":"input","u":"controls.html#input","k":"tag","s":"Single-line text field ( text , password , number ) or checkbox. Supports a blinking caret, mouse and Shift+arrow selection, double-click wo","c":"input .guilib-input-text .guilib-placeholder .guilib-caret .guilib-selection"},{"t":"textarea","u":"controls.html#textarea","k":"function","s":"Multi-line text field with word wrap. Enter inserts a line break; it scrolls vertically when the text is taller than rows lines.","c":"textarea .guilib-textarea-line .guilib-placeholder .guilib-caret .guilib-selection"},{"t":"Toggles","u":"controls.html#toggles","k":"Form controls","s":""},{"t":"checkbox","u":"controls.html#checkbox","k":"function","s":"A label with an input(type = \"checkbox\") and optional text. Clicking the text toggles too.","c":"input[type=checkbox] .guilib-check .guilib-checkbox"},{"t":"switch","u":"controls.html#switch","k":"function","s":"An animated on/off switch (sliding pill). Same onChange as checkbox .","c":".guilib-switch .checked .guilib-switch-track .guilib-switch-thumb .guilib-switch-label"},{"t":"Sliders & numbers","u":"controls.html#sliders-numbers","k":"Form controls","s":""},{"t":"slider","u":"controls.html#slider","k":"function","s":"A range slider like <input type=\"range\"> . There are Float and Int overloads; the type of value picks one.","c":".guilib-slider .dragging .guilib-slider-track .guilib-slider-rail .guilib-slider-fill .guilib-slider-thumb .guilib-slider-field .guilib-slider-value"},{"t":"rangeSlider","u":"controls.html#rangeslider","k":"function","s":"A slider with two thumbs selecting a range, e.g. a filter \"kills between 5,000 and 20,000\". A press moves the nearer thumb; the thumbs can't","c":".guilib-range-slider .guilib-slider-thumb.low .guilib-slider-thumb.high + all .guilib-slider-* classes"},{"t":"numberInput","u":"controls.html#numberinput","k":"function","s":"A number field with − and + buttons that keeps the value within min..max . Values inside the range are reported while typing; anything else ","c":".guilib-number .guilib-number-input .guilib-number-dec .guilib-number-inc"},{"t":"Choices","u":"controls.html#choices","k":"Form controls","s":""},{"t":"select","u":"controls.html#select","k":"function","s":"A dropdown. The menu opens in a portal, so it's never clipped by scroll containers. With searchable = true the menu starts with a search fie","c":"select .guilib-select-value .guilib-select-arrow .guilib-select-menu .guilib-select-search .guilib-select-empty .guilib-option .selected .highlighted .disabled"},{"t":"multiSelect","u":"controls.html#multiselect","k":"function","s":"A dropdown for choosing several options. Each option has a check mark, the menu stays open while toggling and the box shows the chosen label","c":"select.multiple .guilib-option-check + select classes"},{"t":"radioGroup","u":"controls.html#radiogroup","k":"function","s":"Radio buttons (one of several). Like native radios, the selected radio is the Tab stop and the arrow keys move the selection.","c":".guilib-radio-group .vertical .guilib-radio .checked .guilib-radio-dot .guilib-radio-label"},{"t":"segmented","u":"controls.html#segmented","k":"function","s":"Segmented buttons: one of several, joined into a bar with a highlight that slides to the selected segment. Same API as radioGroup .","c":".guilib-segmented .guilib-segment .selected .guilib-segment-indicator"},{"t":"chips","u":"controls.html#chips","k":"function","s":"Toggleable chips for picking several options, e.g. filters. A nicer alternative to multiSelect for a handful of options.","c":".guilib-chips .guilib-chip .selected .guilib-chip-check"},{"t":"Colors","u":"controls.html#colors","k":"Form controls","s":""},{"t":"colorPicker","u":"controls.html#colorpicker","k":"function","s":"An inline color picker: saturation/value area, hue slider, optional alpha slider, hex input and preview. Colors are ARGB Int s.","c":".guilib-color-picker .guilib-cp-sv .guilib-cp-hue .guilib-cp-alpha .guilib-cp-handle .guilib-cp-thumb .guilib-cp-preview .guilib-cp-hex"},{"t":"colorInput","u":"controls.html#colorinput","k":"function","s":"A swatch button showing the color and its hex code that opens a colorPicker in a popover.","c":".guilib-color-input .guilib-color-swatch .guilib-color-hex .guilib-color-popover"},{"t":"SelectBuilder","u":"controls.html#selectbuilder","k":"Form controls","s":""},{"t":"Panels & overlays","u":"overlays.html","k":"page","s":"Navigation, expandable sections, popups and notifications: tabs, accordions, context menus, toasts, tooltips, modals, exit animations and so"},{"t":"Navigation","u":"overlays.html#navigation","k":"Panels & overlays","s":""},{"t":"tabs","u":"overlays.html#tabs","k":"function","s":"A tab bar whose indicator slides to the active tab.","c":".guilib-tabs .underline .pills .guilib-tab-list .guilib-tab .active .guilib-tab-indicator .guilib-tab-panel"},{"t":"Expandable sections","u":"overlays.html#expandable-sections","k":"Panels & overlays","s":""},{"t":"details","u":"overlays.html#details","k":"function","s":"An accordion item like HTML <details> : a clickable summary row with a chevron and a body whose height animates (also when its content chang","c":".guilib-details .open .guilib-details-summary .guilib-details-chevron .guilib-details-title .guilib-details-content"},{"t":"collapse","u":"overlays.html#collapse","k":"function","s":"The building block of details : animates its height between 0 and the height of its content. While open, the height follows the content. Clo","c":".guilib-collapse .open .guilib-collapse-inner"},{"t":"Menus","u":"overlays.html#menus","k":"Panels & overlays","s":""},{"t":"contextMenu","u":"overlays.html#contextmenu","k":"function","s":"A right-click menu for its children: opens at the mouse and is kept inside the screen (it flips up/left near the edges). The entries are bui","c":".guilib-context-anchor .guilib-menu .guilib-menu-item .highlighted .danger .disabled .guilib-menu-label .guilib-menu-shortcut .guilib-menu-header .guilib-menu-separator"},{"t":"Notifications","u":"overlays.html#notifications","k":"Panels & overlays","s":""},{"t":"useToast","u":"overlays.html#usetoast","k":"hook","s":"Short messages that disappear on their own (\"Party created\", \"Server not reachable\"), stacked in the bottom right corner above everything el","c":".guilib-toasts .guilib-toast .info .success .warning .error .leaving .guilib-toast-accent .guilib-toast-title .guilib-toast-message .guilib-toast-close"},{"t":"tooltip","u":"overlays.html#tooltip","k":"function","s":"A tooltip shown when hovering the children for delayMs . For simple text the title prop on any element works too.","c":".guilib-tooltip-anchor .guilib-tooltip"},{"t":"Dialogs & animation","u":"overlays.html#dialogs-animation","k":"Panels & overlays","s":""},{"t":"modal","u":"overlays.html#modal","k":"function","s":"A dialog in a portal with a dimmed backdrop. Escape and (by default) a click on the backdrop call onClose .","c":".guilib-modal-backdrop .guilib-modal"},{"t":"presence","u":"overlays.html#presence","k":"function","s":"Keeps children mounted while they animate out (like Framer Motion's AnimatePresence ). When visible turns false the children render once mor","c":""},{"t":"Lists","u":"overlays.html#lists","k":"Panels & overlays","s":""},{"t":"sortableList","u":"overlays.html#sortablelist","k":"function","s":"A drag-to-reorder list. Items move with transform while dragging; dropping calls onReorder with the reordered list.","c":".guilib-sortable .horizontal .handle .sorting .guilib-sortable-item .dragging .guilib-drag-handle"},{"t":"Events","u":"events.html","k":"page","s":"Events work like the DOM: they bubble from the deepest element to body , and stopPropagation() / preventDefault() behave as you expect."},{"t":"Handling events","u":"events.html#handling-events","k":"Events","s":""},{"t":"Event types","u":"events.html#event-types","k":"Events","s":""},{"t":"Keyboard","u":"events.html#keyboard","k":"Events","s":""},{"t":"Default actions","u":"events.html#default-actions","k":"Events","s":""},{"t":"Focus","u":"events.html#focus","k":"Events","s":""},{"t":"Element API","u":"events.html#element-api","k":"Events","s":""},{"t":"CSS","u":"css.html","k":"page","s":"GuiLib implements the parts of CSS that UIs need, with the real cascade. This page lists every supported selector, value and property."},{"t":"Where styles come from","u":"css.html#where-styles-come-from","k":"CSS","s":""},{"t":"Selectors","u":"css.html#selectors","k":"CSS","s":""},{"t":"Values","u":"css.html#values","k":"CSS","s":""},{"t":"Box model & layout","u":"css.html#layout","k":"CSS","s":""},{"t":"Text & visuals","u":"css.html#text-visuals","k":"CSS","s":""},{"t":"Animation","u":"css.html#animation","k":"CSS","s":""},{"t":"Transforms","u":"css.html#transforms","k":"CSS","s":""},{"t":"Theming built-in controls","u":"css.html#theming","k":"CSS","s":""}];
